"""Money value object."""


class Money:
    """Stores monetary amounts as cents (integer) to avoid floating-point precision issues."""

    def __init__(self, amount: float):
        self.cents = round(amount * 100)

    @property
    def amount(self) -> float:
        """Return the amount as a float for backward compatibility."""
        return self.cents / 100

    def __add__(self, other: "Money") -> "Money":
        result = Money.__new__(Money)
        result.cents = self.cents + other.cents
        return result

    def __mul__(self, qty: int) -> "Money":
        result = Money.__new__(Money)
        result.cents = self.cents * qty
        return result

    def __neg__(self) -> "Money":
        result = Money.__new__(Money)
        result.cents = -self.cents
        return result

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Money):
            return self.cents == other.cents
        return False

    def __hash__(self) -> int:
        return hash(self.cents)

    def __repr__(self) -> str:
        return f"Money({self.amount})"


ZERO = Money(0.0)

